const ROUTE_ON_OPEN_HISTORY_SYNC_COOLDOWN_MS = Math.max(
  Number(process.env.WA_ON_OPEN_HISTORY_SYNC_COOLDOWN_MS || 5 * 60 * 1000),
  30_000,
);
const ROUTE_ON_OPEN_HISTORY_SYNC_ERROR_COOLDOWN_MS = Math.max(
  Number(process.env.WA_ON_OPEN_HISTORY_SYNC_ERROR_COOLDOWN_MS || 30_000),
  5_000,
);
const ROUTE_ON_OPEN_HISTORY_SYNC_SHALLOW_MESSAGE_LIMIT = Math.max(
  Number(process.env.WA_ON_OPEN_HISTORY_SYNC_SHALLOW_MESSAGE_LIMIT || 5),
  1,
);
const routeOnOpenHistorySyncCooldown = new Map<string, number>();

const GATEWAY_SOFT_RECONNECT_COOLDOWN_MS = Math.max(
  Number(process.env.WA_GATEWAY_SOFT_RECONNECT_COOLDOWN_MS || 60_000),
  10_000,
);
const ROUTE_WHATSAPP_QR_MAX_AGE_MS = Math.max(
  Number(process.env.WHATSAPP_QR_MAX_AGE_MS || 60_000),
  30_000,
);

function isGatewayStatusRecoverableWithoutQr(
  connection: {
    id: string;
    isConnected?: boolean | null;
    phoneNumber?: string | null;
    provider?: string | null;
    providerStatus?: string | null;
  },
  status?: GatewayInstanceStatusRecord,
): boolean {
  if (gatewayStatusLooksConnected(status) || status?.qrCode) {
    return false;
  }

  const providerStatus = String(status?.providerStatus || connection.providerStatus || "")
    .trim()
    .toLowerCase();

  if (/logged.?out|logout|unauthorized|invalid/.test(providerStatus)) {
    return false;
  }

  return Boolean(
    isPersistedWhatsAppConnectionOperational({
      isConnected: connection.isConnected === true,
      providerStatus,
      provider: status?.provider || connection.provider || null,
      connectionMethod: null,
    } as any),
  );
}

function triggerGatewaySoftReconnect(connectionId: string, source: string): boolean {
  const cooldownKey = `wa-gateway-soft-reconnect:${connectionId}`;
  if (memoryCache.has(cooldownKey)) {
    return false;
  }

  memoryCache.set(cooldownKey, true, GATEWAY_SOFT_RECONNECT_COOLDOWN_MS);
  connectGatewayInstance(connectionId).catch((error) => {
    console.error(`[WA GATEWAY RECOVERY] Falha no soft reconnect (${source}) para ${connectionId}:`, error);
  });
  return true;
}

async function loadGatewayStatusMapForConnections(
  connections: Array<{ id: string }>,
): Promise<Map<string, GatewayInstanceStatusRecord>> {
  const connectionIds = Array.from(
    new Set(
      connections
        .map((connection) => String(connection.id || "").trim())
        .filter(Boolean),
    ),
  );

  if (connectionIds.length === 0) {
    return new Map();
  }

  return getAppVisibleGatewayBulkStatusMap(connections as any) as Promise<Map<string, GatewayInstanceStatusRecord>>;
}

function mergeConnectionWithGatewayRuntimeStatus<T extends {
  id: string;
  isConnected?: boolean | null;
  phoneNumber?: string | null;
  qrCode?: string | null;
  qrCodeGeneratedAt?: string | null;
  sessionData?: unknown;
  updatedAt?: Date | string | null;
  provider?: string | null;
  providerStatus?: string | null;
}>(connection: T, status?: GatewayInstanceStatusRecord): T {
  if (!status) {
    return sanitizePersistedQrForRoute(connection);
  }

  const visibleQr = getVisibleGatewayOrPersistedQr(connection, status);

  return {
    ...connection,
    isConnected: Boolean(status.isConnected),
    phoneNumber: status.phoneNumber || connection.phoneNumber || null,
    qrCode: visibleQr.qrCode,
    qrCodeGeneratedAt: visibleQr.generatedAt,
    provider: status.provider || connection.provider || null,
    providerStatus: status.providerStatus || connection.providerStatus || null,
  };
}

function parseRouteTimestampMs(value: unknown): number | null {
  if (value instanceof Date) {
    const time = value.getTime();
    return Number.isFinite(time) ? time : null;
  }
  if (typeof value !== "string" || !value.trim()) {
    return null;
  }
  const time = Date.parse(value);
  return Number.isFinite(time) ? time : null;
}

function getConnectionQrGeneratedAtFromSessionData(sessionData: unknown): string | null {
  if (!sessionData || typeof sessionData !== "object" || Array.isArray(sessionData)) {
    return null;
  }

  const runtimeDiagnostics = (sessionData as Record<string, unknown>).runtimeDiagnostics;
  if (!runtimeDiagnostics || typeof runtimeDiagnostics !== "object" || Array.isArray(runtimeDiagnostics)) {
    return null;
  }

  const lastQrCode = (runtimeDiagnostics as Record<string, unknown>).lastQrCode;
  if (!lastQrCode || typeof lastQrCode !== "object" || Array.isArray(lastQrCode)) {
    return null;
  }

  const generatedAt = (lastQrCode as Record<string, unknown>).at;
  return typeof generatedAt === "string" && generatedAt.trim() ? generatedAt.trim() : null;
}

function isFreshRouteQrCode(qrCode: unknown, generatedAt: unknown): boolean {
  if (typeof qrCode !== "string" || !qrCode.trim()) {
    return false;
  }
  const generatedAtMs = parseRouteTimestampMs(generatedAt);
  if (generatedAtMs === null) {
    return false;
  }
  return Date.now() - generatedAtMs < ROUTE_WHATSAPP_QR_MAX_AGE_MS;
}

function getVisiblePersistedConnectionQr(connection: {
  qrCode?: string | null;
  qrCodeGeneratedAt?: string | null;
  sessionData?: unknown;
}): { qrCode: string | null; generatedAt: string | null } {
  const qrCode = typeof connection.qrCode === "string" ? connection.qrCode.trim() : "";
  if (!qrCode) {
    return { qrCode: null, generatedAt: null };
  }

  const generatedAt =
    getConnectionQrGeneratedAtFromSessionData(connection.sessionData) ||
    connection.qrCodeGeneratedAt ||
    null;

  if (!isFreshRouteQrCode(qrCode, generatedAt)) {
    return { qrCode: null, generatedAt: null };
  }

  return { qrCode, generatedAt: generatedAt || null };
}

function sanitizePersistedQrForRoute<T extends {
  qrCode?: string | null;
  qrCodeGeneratedAt?: string | null;
  sessionData?: unknown;
}>(connection: T): T {
  const visibleQr = getVisiblePersistedConnectionQr(connection);
  if (visibleQr.qrCode) {
    return {
      ...connection,
      qrCode: visibleQr.qrCode,
      qrCodeGeneratedAt: visibleQr.generatedAt,
    };
  }

  return {
    ...connection,
    qrCode: null,
    qrCodeGeneratedAt: null,
  };
}

function getVisibleGatewayOrPersistedQr(
  connection: {
    qrCode?: string | null;
    qrCodeGeneratedAt?: string | null;
    sessionData?: unknown;
  },
  status?: GatewayInstanceStatusRecord,
): { qrCode: string | null; generatedAt: string | null } {
  const persistedQr = getVisiblePersistedConnectionQr(connection);
  const statusQrCode = typeof status?.qrCode === "string" ? status.qrCode.trim() : "";
  if (statusQrCode) {
    const statusGeneratedAt =
      status?.qrCodeGeneratedAt ||
      (persistedQr.qrCode === statusQrCode ? persistedQr.generatedAt : null);
    if (!isFreshRouteQrCode(statusQrCode, statusGeneratedAt)) {
      return { qrCode: null, generatedAt: null };
    }
    return {
      qrCode: statusQrCode,
      generatedAt: statusGeneratedAt || null,
    };
  }

  return persistedQr;
}

const ROUTE_LOCAL_AUTO_RECOVERY_BLOCKED_STATUSES = new Set([
  "auth_failed",
  "device_removed",
  "disconnected",
  "invalid_session",
  "logged_out",
  "logout",
  "manual_disconnect",
  "manual_disconnected",
  "not_connected",
  "open_timeout",
  "pairing_failed",
  "pairing_required",
  "phone_conflict_other_user",
  "qr_required",
  "removed",
  "unauthorized",
]);

function shouldRouteStartLocalSessionRecovery(
  connection: {
    isConnected?: boolean | null;
    providerStatus?: string | null;
  },
  hasPersistedAuth: boolean,
): boolean {
  if (!hasPersistedAuth || connection.isConnected !== true) {
    return false;
  }

  const providerStatus = String(connection.providerStatus || "").trim().toLowerCase();
  if (!providerStatus) {
    return true;
  }

  if (ROUTE_LOCAL_AUTO_RECOVERY_BLOCKED_STATUSES.has(providerStatus)) {
    return false;
  }

  return !/logged.?out|logout|unauthorized|invalid|removed|qr|required|timeout/.test(providerStatus);
}

