  app.post("/api/admin/users/:id/reset-agent-creator-state", isAdmin, async (req, res) => {

    const { id } = req.params;

    try {

      const user = await storage.getUser(id);
      if (!user) return res.status(404).json({ message: "User not found" });

      const { phoneNumber, reason } = req.body || {};
      const { resetAdminAgentLeadState } = await import("./adminAgentService");
      const result = await resetAdminAgentLeadState({
        userId: id,
        phoneNumber: typeof phoneNumber === "string" ? phoneNumber : undefined,
        reason: typeof reason === "string" ? reason : "admin_reset_agent_creator_state",
      });

      res.json(result);

    } catch (error: any) {

      console.error("[ADMIN] Error resetting agent creator state:", error);
      res.status(500).json({ message: error?.message || "Error resetting agent creator state" });

    }

  });



