  // Get user agent config

  app.get("/api/admin/users/:id/agent-config", isAdmin, async (req, res) => {

    const { id } = req.params;

    try {
      const legacyConfig = await storage.getAgentConfig(id);
      if (legacyConfig) {
        return res.json(legacyConfig);
      }

      const businessConfig = await storage.getBusinessAgentConfig(id);
      return res.json({
        prompt: "",
        isActive: businessConfig?.isActive || false,
        triggerPhrases: [],
        model: businessConfig?.model || "gpt-5.4-mini",
        llmConfig: { mode: "global" },
      });

    } catch (error) {

      res.status(500).json({ message: "Error fetching user agent config" });

    }

  });



