  // DELETE a connection for the authenticated user
  app.delete("/api/whatsapp/connections/:connectionId", isAuthenticated, async (req: any, res) => {
    try {
      const userId = getUserId(req);
      const connection = await storage.getConnectionById(req.params.connectionId);
      if (!connection || connection.userId !== userId) {
        return res.status(404).json({ message: "Conexao nao encontrada" });
      }
      if (isUserRemovedConnection(connection)) {
        return res.json({
          success: true,
          mergedIntoConnectionId: null,
          preservedHistory: true,
          blockedByHistory: false,
        });
      }
      // Don't allow deleting the primary connection
      if ((connection as any).isPrimary) {
        return res.status(400).json({ message: "Nao e possivel deletar a conexao principal" });
      }

      if (!isGatewayClientEnabled()) {
        const deleteResult = await deleteConnectionSafely(req.params.connectionId);
        memoryCache.invalidate(`api:wa-conn:${userId}`);
        memoryCache.invalidate(`api:wa-conn:${userId}:default`);
        return res.json({
          success: true,
          mergedIntoConnectionId: deleteResult.mergedIntoConnectionId || null,
          preservedHistory: deleteResult.preservedHistory === true,
          blockedByHistory: false,
        });
      }

      const deleteResult = await deleteGatewayManagedInstance(req.params.connectionId) as any;
      if (deleteResult.blockedByHistory) {
        return res.status(400).json({
          message: "Esta conexao possui historico de conversas. Desconecte em vez de excluir para preservar o atendimento.",
          blockedByHistory: true,
        });
      }

      memoryCache.invalidate(`api:wa-conn:${userId}`);
      res.json({
        success: true,
        mergedIntoConnectionId: deleteResult.mergedIntoConnectionId || null,
        preservedHistory: deleteResult.preservedHistory === true,
      });
    } catch (error) {
      console.error("[MULTI-CONN] Erro ao deletar conexao:", error);
      res.status(500).json({ message: "Erro ao deletar conexao" });
    }
  });

