  // =============================================



  const getProductsCatalogStats = async (userId: string) => {
    const result = await pool.query(
      "SELECT COUNT(*)::int AS count FROM products WHERE user_id = $1",
      [userId],
    );
    const productCount = Number(result.rows[0]?.count || 0);
    return {
      productCount,
      hasProducts: productCount > 0,
    };
  };

  const normalizeProductsConfigForCatalogAvailability = async (userId: string, config: any) => {
    const stats = await getProductsCatalogStats(userId);

    if (!config) {
      return {
        config: null,
        ...stats,
      };
    }

    if (
      !stats.hasProducts &&
      (
        config.is_active === true ||
        config.send_to_ai === true ||
        config.image_variations_enabled === true
      )
    ) {
      const normalizedResult = await pool.query(
        `
          UPDATE products_config
          SET is_active = false,
              send_to_ai = false,
              image_variations_enabled = false,
              updated_at = NOW()
          WHERE user_id = $1
          RETURNING *
        `,
        [userId],
      );
      const normalizedConfig = normalizedResult.rows[0] || {
        ...config,
        is_active: false,
        send_to_ai: false,
        image_variations_enabled: false,
      };

      return {
        config: normalizedConfig,
        ...stats,
      };
    }

    return {
      config,
      ...stats,
    };
  };

