  app.get("/api/products-config", isAuthenticated, async (req: any, res) => {

    try {

      const userId = getUserId(req);



      const configResult = await pool.query(
        "SELECT * FROM products_config WHERE user_id = $1 LIMIT 1",
        [userId],
      );
      let data = configResult.rows[0];

      if (!data) {
        const insertResult = await pool.query(
          `
            INSERT INTO products_config (
              user_id, is_active, send_to_ai, image_variations_enabled, updated_at
            )
            VALUES ($1, false, false, false, NOW())
            ON CONFLICT (user_id) DO UPDATE SET
              updated_at = products_config.updated_at
            RETURNING *
          `,
          [userId],
        );
        data = insertResult.rows[0];
      }

      const normalized = await normalizeProductsConfigForCatalogAvailability(userId, data);

      res.json({
        ...normalized.config,
        has_products: normalized.hasProducts,
        product_count: normalized.productCount,
      });

    } catch (error) {

      console.error("Error fetching products config:", error);

      res.status(500).json({ message: "Failed to fetch products config" });

    }

  });



