  app.put("/api/delivery/categories/:id", isAuthenticated, async (req: any, res) => {

    try {

      const userId = getUserId(req);

      const { id } = req.params;

      const { name, description, imageUrl, displayOrder, isActive, halfHalfPricing } = req.body;



      const updateData: any = { updated_at: new Date().toISOString() };

      if (name !== undefined) updateData.name = name;

      if (description !== undefined) updateData.description = description;

      if (imageUrl !== undefined) updateData.image_url = imageUrl;

      if (displayOrder !== undefined) updateData.display_order = displayOrder;

      if (isActive !== undefined) updateData.is_active = isActive;

      if (halfHalfPricing !== undefined) updateData.half_half_pricing = normalizeHalfHalfPricingPayload(halfHalfPricing);



      const { data, error } = await supabase

        .from('menu_categories')

        .update(updateData)

        .eq('id', id)

        .eq('user_id', userId)

        .select()

        .single();



      if (error) throw error;



      res.json(data);

    } catch (error) {

      console.error("Error updating menu category:", error);

      res.status(500).json({ message: "Failed to update menu category" });

    }

  });



