  function withPromptEditStreamTimeout<T>(promise: Promise<T>, timeoutMs: number): Promise<T> {
    const safeTimeoutMs = Math.max(15_000, timeoutMs);
    let timer: NodeJS.Timeout | null = null;

    return Promise.race([
      promise.finally(() => {
        if (timer) clearTimeout(timer);
      }),
      new Promise<T>((_, reject) => {
        timer = setTimeout(() => {
          reject(new Error(`prompt_edit_stream_timeout:${safeTimeoutMs}`));
        }, safeTimeoutMs);
      }),
    ]);
  }

