  function buildPromptEditValidationFailedFeedback(calibrationResult?: any, fallbackMessage?: string): string {
    const score = calibrationResult && Number.isFinite(Number(calibrationResult.scoreGeral))
      ? ` Pontuacao: ${Number(calibrationResult.scoreGeral)}/100.`
      : "";
    const reason = String(fallbackMessage || "").trim();
    return [
      "Nao apliquei ainda. Os testes do agente nao confirmaram que essa mudanca funciona com seguranca.",
      score.trim(),
      reason ? `Motivo: ${reason}` : "",
      "Ajuste a instrucao e tente novamente.",
    ].filter(Boolean).join(" ");
  }

  function normalizePromptEditSimulatorHistory(value: unknown): Array<{ role: "user" | "assistant"; content: string }> {
    if (!Array.isArray(value)) return [];

    return value
      .map((item: any) => {
        const role = item?.role === "assistant" ? "assistant" : "user";
        const content = String(item?.content || "").trim();
        return content ? { role, content } : null;
      })
      .filter(Boolean)
      .slice(-40) as Array<{ role: "user" | "assistant"; content: string }>;
  }

  function normalizePromptEditSentMedias(value: unknown): string[] {
    if (!Array.isArray(value)) return [];

    return Array.from(new Set(
      value
        .map((item) => String(item || "").trim())
        .filter(Boolean)
        .map((item) => item.toUpperCase())
    )).slice(-80);
  }

  function buildPromptCalibrationRepairInstruction(repairInput: {
    instrucaoUsuario: string;
    cenarioFalhou: any;
    resultadoFalhou: any;
    rodada: number;
  }): string {
    const cenario = repairInput.cenarioFalhou || {};
    const resultado = repairInput.resultadoFalhou || {};
    const historico = Array.isArray(cenario.historico)
      ? cenario.historico
        .slice(-8)
        .map((message: any) => {
          const role = message?.role === "assistant" ? "Agente" : "Cliente";
          return `${role}: ${String(message?.content || "").trim()}`;
        })
        .filter(Boolean)
        .join("\n")
      : "";

    return [
      "Revise a configuracao do agente para corrigir a falha encontrada no teste real.",
      "Ajuste somente o necessario para o pedido original funcionar; preserve identidade, tom, regras, midias, funil, catalogo, agenda, precos e todo comportamento que nao esteja relacionado.",
      "Nao remova informacoes existentes. Nao invente regra especifica de um cliente se ela nao estiver no pedido original.",
      "",
      `Pedido original: ${String(repairInput.instrucaoUsuario || "").trim()}`,
      `Rodada de ajuste: ${repairInput.rodada}`,
      "",
      "Teste que falhou:",
      `Cliente perguntou: ${String(cenario.perguntaCliente || "").trim()}`,
      historico ? `Historico do teste:\n${historico}` : "",
      `Resposta esperada: ${String(cenario.expectativaResposta || "").trim()}`,
      `Resposta atual do agente: ${String(resultado.respostaAgente || "").trim()}`,
      `Pontuacao: ${Number(resultado.score || 0)}/100`,
      `Motivo: ${String(resultado.motivo || "").trim()}`,
      "",
      "Entregue uma nova versao completa da configuracao, mantendo todas as partes validas e corrigindo a falha acima.",
    ].filter(Boolean).join("\n");
  }

  function createPromptCalibrationRepairEditor(params: {
    userId: string;
    sendEvent?: (data: any) => void;
  }) {
    return async (repairInput: any) => {
      const repairInstruction = buildPromptCalibrationRepairInstruction(repairInput);
      params.sendEvent?.({
        type: "calibration_log",
        logType: "repair_start",
        message: "Ajustando novamente com base no teste que falhou...",
        timestamp: Date.now(),
      });

      const repairResult = await withPromptEditStreamTimeout(
        editarPromptViaIA(
          repairInput.promptAtual,
          repairInstruction,
          "",
          "codex",
          {
            userId: params.userId,
            conversationId: `prompt-edit-repair:${params.userId}`,
            onProgress: (message) => params.sendEvent?.({
              type: "calibration_log",
              logType: "repair_start",
              message: `Ajuste em andamento: ${message}`,
              timestamp: Date.now(),
            }),
          },
        ),
        PROMPT_EDIT_STREAM_ATTEMPT_TIMEOUT_MS,
      );

      if (!repairResult.success || !repairResult.novoPrompt || repairResult.novoPrompt === repairInput.promptAtual) {
        return {
          promptReparado: null,
          edicoesAplicadas: 0,
          mensagem: repairResult.mensagemChat || "Ajuste nao alterou a configuracao.",
        };
      }

      return {
        promptReparado: repairResult.novoPrompt,
        edicoesAplicadas: Math.max(1, Number(repairResult.edicoesAplicadas || 0)),
        mensagem: repairResult.mensagemChat,
      };
    };
  }

  app.get("/api/daily-limits", isAuthenticated, async (req: any, res) => {

    try {

      const userId = getUserId(req);

      // Use canonical entitlement helper (same logic as /api/access-status)
      const entitlement = await getAccessEntitlement(userId);
      const hasActiveSubscription = entitlement.hasActiveSubscription;



      // Plano pago = limites ilimitados

      if (hasActiveSubscription) {

        return res.json({

          hasActiveSubscription: true,

          calibration: {

            used: 0,

            limit: -1,

            remaining: -1,

            isLimitReached: false,

          },

          simulator: {

            used: 0,

            limit: -1,

            remaining: -1,

            isLimitReached: false,

          },

        });

      }



      const dailyUsage = await storage.getDailyUsage(userId);



      res.json({

        hasActiveSubscription: false,

        calibration: {

          used: 0,

          limit: -1,

          remaining: -1,

          isLimitReached: false,

          isUnlimited: true,

        },

        simulator: {

          used: dailyUsage.simulatorMessagesCount,

          limit: FREE_DAILY_SIMULATOR_LIMIT,

          remaining: Math.max(0, FREE_DAILY_SIMULATOR_LIMIT - dailyUsage.simulatorMessagesCount),

          isLimitReached: dailyUsage.simulatorMessagesCount >= FREE_DAILY_SIMULATOR_LIMIT,

        },

      });

    } catch (error) {

      console.error("Error fetching daily limits:", error);

      res.status(500).json({ message: "Failed to fetch daily limits" });

    }

  });



