  app.post("/api/agent/test", isAuthenticated, async (req: any, res) => {

    try {

      const userId = getUserId(req);

      console.log(`[/api/agent/test] ENTRADA - userId: ${userId}, message: ${req.body.message?.substring(0, 30)}`);

      const accessBlock = await resolveUserAccessBlockForBillableAction(userId);
      if (accessBlock) {
        return res.status(402).json({
          success: false,
          blocked: true,
          mode: "access_blocked",
          blockReason: accessBlock.blockReason,
          message: accessBlock.message,
          response: "",
          mediaActions: [],
          splitResponses: [],
        });
      }

      const channelGuard = await getSimulatorChannelGuardResult(userId);
      if (!channelGuard.channelReady) {
        return res.json({
          success: false,
          channelReady: false,
          blockSource: channelGuard.blockSource,
          blockReason: channelGuard.blockReason,
          response: channelGuard.blockReason,
          mediaActions: [],
          splitResponses: [],
        });
      }



      // Check daily simulator limit for free users.

      const entitlementSim = await getAccessEntitlement(userId);

      const hasActiveSubscription = entitlementSim.hasActiveSubscription;



      if (!hasActiveSubscription) {

        const dailyUsage = await storage.getDailyUsage(userId);

        if (dailyUsage.simulatorMessagesCount >= FREE_DAILY_SIMULATOR_LIMIT) {

          return res.json({

            success: false,

            limitReached: true,

            used: dailyUsage.simulatorMessagesCount,

            limit: FREE_DAILY_SIMULATOR_LIMIT,

          });

        }

        // Incrementar contador de mensagens do simulador para usuarios free.

        await storage.incrementSimulatorMessages(userId);

      }



      const schema = z.object({

        message: z.string(),

        customPrompt: z.string().optional(),

        // Suporte para historico de conversa do simulador unificado.

        history: z.array(z.object({

          role: z.enum(["user", "assistant"]),

          content: z.string()

        })).optional(),

        // Midias ja enviadas nesta sessao do simulador.

        sentMedias: z.array(z.string()).optional(),
        mediaItems: z.array(z.object({
          mediaType: z.string().optional(),
          media_url: z.string().optional(),
          mediaUrl: z.string().optional(),
          mediaUrlOriginal: z.string().optional(),
          media_url_original: z.string().optional(),
          caption: z.string().optional(),
          text: z.string().optional(),
          mediaCaption: z.string().optional(),
          media_caption: z.string().optional(),
          url: z.string().optional(),
        })).optional(),
        mediaUrl: z.string().optional(),
        mediaType: z.string().optional(),
        mediaUrlOriginal: z.string().optional(),
        sessionId: z.string().optional(),
        conversationId: z.string().optional(),
        conversationKey: z.string().optional(),
        testConversationKey: z.string().optional(),
        contactPhone: z.string().optional(),
        contactNumber: z.string().optional(),
        phone: z.string().optional(),
        clearCart: z.boolean().optional(),

        // Nome do contato para simulacao.

        contactName: z.string().optional(),

        // Permite simular resposta em audio quando o cliente mandou audio.
        customerMessageWasAudio: z.boolean().optional()

      });

      const result = schema.safeParse(req.body);



      if (!result.success) {

        return res.status(400).json({ message: "Invalid request" });

      }



      // Converter historico do frontend para formato Message[].

      const conversationHistory = result.data.history?.map((msg, idx) => ({

        id: `sim-${idx}`,

        chatId: "simulator",

        text: msg.content,

        fromMe: msg.role === "assistant",

        timestamp: new Date(Date.now() - (result.data.history!.length - idx) * 60000),

        isFromAgent: msg.role === "assistant",

      })) || [];

      const agendamento3ProbeText = [
        result.data.message,
        ...(result.data.history || []).map((entry) => entry.content),
      ].join("\n").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
      const shouldTryAgendamento3Direct =
        /\b(agend|agenda|horario|disponivel|marcar|remarcar|cancelar|confirmar|combinado|visita|atendimento)\b/.test(agendamento3ProbeText);

      if (shouldTryAgendamento3Direct) {
        try {
          const agendamento3Config = await pool.query(
            `
              SELECT is_active, agentic_mode_enabled
              FROM agendamento3_config
              WHERE user_id = $1
              LIMIT 1
            `,
            [userId],
          );
          const agendamento3Row = agendamento3Config.rows[0];
          if (agendamento3Row?.is_active === true && agendamento3Row?.agentic_mode_enabled !== false) {
            const configuredInternalUrl = String(
              process.env.AGENDAMENTO3_INTERNAL_AGENT_URL ||
                process.env.INTERNAL_APP_URL ||
                "",
            ).trim();
            const internalAgentUrl = configuredInternalUrl
              ? configuredInternalUrl.replace(/\/+$/, "") + "/api/test-agent/message"
              : `http://127.0.0.1:${String(process.env.PORT || "5000").trim() || "5000"}/api/test-agent/message`;
            const agendamento3Response = await fetch(internalAgentUrl, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                userId,
                message: result.data.message,
                history: result.data.history || [],
                contactName: result.data.contactName,
                contactPhone: req.body?.contactPhone || req.body?.contactNumber || req.body?.phone || null,
                conversationId: req.body?.conversationId || req.body?.conversationKey || req.body?.testConversationKey || null,
                forceAgendamento3: true,
                agendamento3Commit: false,
                flow2RuntimeEnabled: false,
                skipAccessCheck: true,
              }),
              signal: AbortSignal.timeout(60_000),
            });
            const agendamento3Payload: any = await agendamento3Response.json().catch(() => ({}));
            if (
              agendamento3Response.ok &&
              agendamento3Payload?.mode === "agendamento3" &&
              agendamento3Payload?.agendamento3?.handled
            ) {
              return res.json({
                response: agendamento3Payload.response || "",
                splitResponses: agendamento3Payload.splitResponses || (agendamento3Payload.response ? [agendamento3Payload.response] : []),
                mediaActions: [],
                audioResponseMode: "text",
                wouldSendAudio: false,
                wouldSendText: Boolean(agendamento3Payload.response),
                mode: "agendamento3",
                agendamento3: agendamento3Payload.agendamento3,
              });
            }
          }
        } catch (agendamento3Error: any) {
          console.warn("[/api/agent/test] Agendamento 3.0 direct simulator fallback:", agendamento3Error?.message || agendamento3Error);
        }
      }



      // Aceita prompt customizado para testar mudancas nao salvas

      // Aceita nome de contato customizado para simulacao mais realista

      let simulatorMediaLibrary: any[] | null = null;
      const getSimulatorMediaLibraryOnce = async () => {
        if (!simulatorMediaLibrary) {
          simulatorMediaLibrary = await getAgentMediaLibrary(userId);
        }
        return simulatorMediaLibrary;
      };

      const buildSimulatorFinalCandidate = async (rawResult: any) => {
        const simulatorTestResult = rawResult && typeof rawResult === "object"
          ? rawResult
          : { text: "", mediaActions: [] };
        const simulatorMediaActions = Array.isArray(simulatorTestResult.mediaActions)
          ? simulatorTestResult.mediaActions
          : [];
        const mediaActions: any[] = [];
        const flowTextParts: string[] = [];
        const unresolvedActions: any[] = [];
        const hasBaseText = Boolean(String(simulatorTestResult.text || "").trim());
        const hasNonTextMediaAction = Boolean(
          simulatorMediaActions.some((action: any) => action?.type !== "send_text"),
        );

        if (simulatorMediaActions.length > 0) {
          const mediaLibrary = await getSimulatorMediaLibraryOnce();

          for (const action of simulatorMediaActions) {
            if (action?.type === "send_text" && action.text) {
              const textAction = String(action.text).trim();
              if (!textAction) {
                continue;
              }

              if (hasBaseText || hasNonTextMediaAction) {
                mediaActions.push({
                  type: "send_text",
                  text: textAction,
                });
              } else {
                flowTextParts.push(textAction);
              }
              continue;
            }

            const expandedActions = expandSimulatorMediaAction(action, mediaLibrary, result.data.contactName);
            if (expandedActions.length > 0 && action?.media_name) {
              console.log(`[/api/agent/test] Midia expandida: ${action.media_name} -> ${expandedActions.length} acao(oes)`);
            }
            if (expandedActions.length === 0 && String(action?.media_name || action?.media_url || "").trim()) {
              unresolvedActions.push({
                type: action?.type || null,
                mediaName: action?.media_name || action?.mediaName || null,
                hasMediaUrl: Boolean(action?.media_url || action?.mediaUrl),
              });
            }
            mediaActions.push(...expandedActions);
          }
        }

        const baseText = simulatorTestResult.text || "";
        const responseText = flowTextParts.length > 0 && !baseText
          ? flowTextParts.join("\n\n")
          : baseText;
        const explicitBubbleMessages = parseExplicitBubbleMessages(responseText);
        const splitMessages = explicitBubbleMessages.parts;

        if (explicitBubbleMessages.hasExplicitBubbles) {
          console.log(`[SIMULADOR] IA dividiu em ${splitMessages.length} bolhas via [BOLHA]`);
        }

        return {
          raw: simulatorTestResult,
          responseText,
          splitMessages,
          mediaActions,
          unresolvedActions,
        };
      };

      const runRealWebOnlySimulatorRuntime = async (reason: string) => {
        try {
          const { runWebOnlyAgentTestForUser } = await import("../api/http");
          const webOnlyRetry = await runWebOnlyAgentTestForUser(userId, {
            message: result.data.message,
            customPrompt: result.data.customPrompt,
            history: result.data.history || [],
            sentMedias: result.data.sentMedias || [],
            mediaItems: result.data.mediaItems || [],
            mediaUrl: result.data.mediaUrl,
            mediaType: result.data.mediaType,
            mediaUrlOriginal: result.data.mediaUrlOriginal,
            sessionId: result.data.sessionId,
            conversationId: result.data.conversationId || result.data.conversationKey || result.data.testConversationKey || null,
            conversationKey: result.data.conversationKey || result.data.conversationId || result.data.testConversationKey || null,
            testConversationKey: result.data.testConversationKey || result.data.conversationId || result.data.conversationKey || null,
            clearCart: result.data.clearCart === true,
            contactName: result.data.contactName,
            contactPhone: result.data.contactPhone || result.data.contactNumber || result.data.phone || null,
            customerMessageWasAudio: result.data.customerMessageWasAudio === true,
            flow2RuntimeEnabled: true,
            skipAccessCheck: true,
          });
          const webOnlyPayload: any = webOnlyRetry?.payload || {};
          const webOnlySplitResponses = Array.isArray(webOnlyPayload.splitResponses)
            ? webOnlyPayload.splitResponses.filter((part: any) => String(part || "").trim())
            : [];
          const webOnlyMediaActions = Array.isArray(webOnlyPayload.mediaActions) ? webOnlyPayload.mediaActions : [];
          const webOnlyResponseText = String(webOnlyPayload.response || "").trim();
          if (
            webOnlyRetry.status >= 200 &&
            webOnlyRetry.status < 300 &&
            (webOnlySplitResponses.length > 0 || webOnlyMediaActions.length > 0 || webOnlyResponseText)
          ) {
            console.warn("[/api/agent/test] Real web-only simulator runtime produced final payload", {
              userId,
              sessionId: result.data.sessionId || null,
              reason,
              splitCount: webOnlySplitResponses.length,
              mediaCount: webOnlyMediaActions.length,
              mode: webOnlyPayload.mode || null,
            });
            return webOnlyPayload;
          }
          console.warn("[/api/agent/test] Real web-only simulator runtime returned no final payload", {
            userId,
            sessionId: result.data.sessionId || null,
            reason,
            status: webOnlyRetry?.status || null,
            mode: webOnlyPayload.mode || null,
            emptyResponse: webOnlyPayload.emptyResponse === true,
          });
        } catch (webOnlyRuntimeError: any) {
          console.warn("[/api/agent/test] Real web-only simulator runtime failed", {
            userId,
            sessionId: result.data.sessionId || null,
            reason,
            error: webOnlyRuntimeError?.message || String(webOnlyRuntimeError),
          });
        }
        return null;
      };

      // Keep the authenticated simulator aligned with the public/WhatsApp web-only Codex runtime.
      const webOnlyPrimaryPayload = await runRealWebOnlySimulatorRuntime("codex_primary");
      if (webOnlyPrimaryPayload) {
        return res.status(200).json(webOnlyPrimaryPayload);
      }
      return res.status(502).json({
        success: false,
        emptyResponse: true,
        mode: "codex_runtime_required_failed",
        message: "O simulador nao recebeu uma resposta do agente. Tente novamente ou revise a configuracao antes de testar.",
        response: "",
        splitResponses: [],
        mediaActions: [],
      });

    } catch (error: any) {

      console.error("Error testing agent:", error);

      res.status(500).json({ message: error.message || "Failed to test agent" });

    }

  });



