  // ==================== SUBSCRIPTIONS ROUTES ====================

  // Get current user subscription

  app.get("/api/subscriptions/current", isAuthenticated, async (req: any, res) => {

    try {

      const userId = getUserId(req);

      // PERF: Response cache (120s TTL)
      const subCacheKey = `api:subscription:${userId}`;
      const subData = await memoryCache.getOrCompute(subCacheKey, async () => {
        const subscription = await storage.getUserSubscription(userId);
        return subscription || null;
      }, 120_000);
      res.json(subData);

    } catch (error) {

      console.error("Error fetching subscription:", error);

      res.status(500).json({ message: "Failed to fetch subscription" });

    }

  });



  // Get subscription by ID

  app.get("/api/subscriptions/:id", isAuthenticated, async (req: any, res) => {

    try {

      const userId = getUserId(req);

      const { id } = req.params;



      const subscription = await storage.getSubscription(id) as any;



      if (!subscription) {

        return res.status(404).json({ message: "Subscription not found" });

      }



      // Check if user owns this subscription or is admin

      const user = await storage.getUser(userId) as any;

      if (subscription.userId !== userId && user?.role !== 'admin') {

        return res.status(403).json({ message: "Access denied" });

      }



      // Include plan data

      const plan = await storage.getPlan(subscription.planId);
      const effectivePlan = plan
        ? {
            ...plan,
            valorPrimeiraCobranca: (
              await resolveSubscriptionChargeAmounts({
                userId,
                subscriptionId: subscription.id,
                plan,
                couponPrice: subscription.couponPrice,
              })
            ).hasDifferentFirstCharge
              ? plan.valorPrimeiraCobranca
              : null,
          }
        : null;

      res.json({ ...subscription, plan: effectivePlan });

    } catch (error) {

      console.error("Error fetching subscription by ID:", error);

      res.status(500).json({ message: "Failed to fetch subscription" });

    }

  });

  app.get("/api/plans/promo-eligibility", isAuthenticated, async (req: any, res) => {
    try {
      const userId = getUserId(req);
      const introOfferEligible = !(await hasCompletedSubscriptionHistory(userId));
      res.json({ introOfferEligible });
    } catch (error) {
      console.error("Error fetching plan promo eligibility:", error);
      res.status(500).json({ message: "Failed to fetch plan promo eligibility" });
    }
  });



