  app.get("/api/checkout/config", async (req, res) => {
    try {
      const [pixManualConfig, pixKeyConfig] = await Promise.all([
        storage.getSystemConfig('pix_manual_enabled'),
        storage.getSystemConfig('pix_key'),
      ]);

      const pixManualEnabled = readEnabledConfig(pixManualConfig?.valor, true);

      res.json({
        pix_manual_enabled: pixManualEnabled,
        has_pix_key: !!pixKeyConfig?.valor,
      });
    } catch (error) {
      console.error("Error fetching checkout config:", error);
      res.status(500).json({ message: "Failed to fetch checkout config" });
    }
  });

  // Update Codex-only operational config

  app.put("/api/admin/config", isAdmin, async (req, res) => {

    try {

      const { pix_key, pix_manual_enabled } = req.body || {};

      if (pix_key !== undefined) {
        await storage.updateSystemConfig("pix_key", String(pix_key || "").trim());
      }

      if (pix_manual_enabled !== undefined) {
        await storage.updateSystemConfig("pix_manual_enabled", readEnabledConfig(pix_manual_enabled, true) ? "true" : "false");
      }


      res.json({ success: true, codex_runtime: "context_only" });

    } catch (error) {

      console.error("Error updating config:", error);

      res.status(500).json({ message: "Failed to update config" });

    }

  });

  // ==================== AI ATTENDANCE QUEUE STATUS API ====================

  app.get("/api/admin/ai-queue/status", isAdmin, async (req, res) => {
    const normalizeAdminQueueReason = (value: unknown): string => {
      const text = String(value || "").replace(/\s+/g, " ").trim();
      if (!text) return "";
      const normalized = text.toLowerCase();
      if (normalized.includes("timeout") || normalized.includes("timedout")) {
        return "Tempo de processamento esgotado";
      }
      if (normalized.includes("402") || normalized.includes("credits") || normalized.includes("creditos")) {
        return "Limite de processamento atingido";
      }
      if (
        
        normalized.includes("providererror") ||
        normalized.includes("apierror") ||
        normalized.includes("sessionid") ||
        normalized.includes("messageid") ||
        normalized.includes("step_start") ||
        normalized.includes("stack") ||
        /(?:^|[\\/])(?:server|dist|api|client)[\\/][^ ]+\.(?:ts|js|tsx|jsx)(?::\d+)?/i.test(text)
      ) {
        return "Resposta em nova tentativa";
      }
      if (
        /\b(json|schema|parse|parser|tool|model|provider|runtime|agent|ai|ia|vercel|sdk|endpoint|api)\b/.test(
          normalized,
        )
      ) {
        return "Resposta em nova tentativa";
      }
      return text;
    };

    const sanitizeAdminQueueText = (value: unknown, maxLength = 160): string => {
      let text = normalizeAdminQueueReason(value);
      if (!text) return "";
      text = text
        .replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/gi, "Bearer [removido]")
        .replace(/sk-[A-Za-z0-9_-]{12,}/g, "[chave removida]")
        .replace(/\bsb_(?:secret|service_role|publishable)_[A-Za-z0-9._-]+/gi, "[chave removida]")
        .replace(/\beyJ[A-Za-z0-9._-]{20,}\b/g, "[token removido]")
        .replace(/\b(?:api[_-]?key|access[_-]?token|refresh[_-]?token|token|secret|authorization)\s*[:=]\s*["']?[A-Za-z0-9._~+/=-]{8,}/gi, "[segredo removido]")
        .replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, "[email]")
        .replace(/\b\d{8,}\b/g, (match) => `final ${match.slice(-4)}`);
      return text.length > maxLength ? `${text.slice(0, maxLength - 1).trim()}...` : text;
    };

    const maskAdminQueuePhone = (value: unknown): string => {
      const digits = String(value || "").replace(/\D+/g, "");
      return digits ? `final ${digits.slice(-4)}` : "";
    };

    const stableAdminLabel = (value: unknown, prefix: string): string => {
      const text = String(value || "").trim();
      if (!text) return "-";
      let hash = 0;
      for (let index = 0; index < text.length; index += 1) {
        hash = ((hash << 5) - hash + text.charCodeAt(index)) | 0;
      }
      return `${prefix} ${Math.abs(hash).toString(36).slice(0, 6)}`;
    };

    const normalizeAdminRuntimeStage = (value: unknown): string => {
      const text = String(value || "").trim().toLowerCase();
      if (!text) return "atendimento";
      if (text.includes("aguard")) return "aguardando";
      if (text.includes("montando")) return "preparando atendimento";
      if (text.includes("tentando")) return "nova tentativa";
      if (text.includes("conclu")) return "concluido";
      if (text.includes("rapida")) return "validacao rapida";
      if (text.includes("principal")) return "resposta principal";
      if (text.includes("reserva")) return "rota alternativa";
      return "processando atendimento";
    };

    const normalizeAdminEventKind = (value: unknown): string => {
      const text = String(value || "").trim().toLowerCase();
      if (text === "queued") return "queued";
      if (text === "started") return "started";
      if (text === "target_started") return "processing";
      if (text === "target_failed") return "retrying";
      if (text === "completed") return "completed";
      if (text === "failed") return "failed";
      if (text === "released") return "released";
      return "processing";
    };

    const normalizeAdminConnectionEventType = (value: unknown): string => {
      const text = String(value || "").trim().toLowerCase();
      if (text === "connected") return "connected";
      if (text === "disconnected") return "disconnected";
      if (text === "messages_recovered") return "messages_recovered";
      return "connection_event";
    };

    const normalizeAdminDeliveryStatus = (value: unknown): string | null => {
      const text = String(value || "").trim().toLowerCase();
      if (!text) return null;
      if (["pending", "queued", "sending", "sent", "delivered", "read", "failed"].includes(text)) return text;
      return sanitizeAdminQueueText(text, 40) || null;
    };

    const normalizeAdminRecentSource = (value: unknown): "principal" | "timer" | "all" => {
      const text = String(value || "").trim().toLowerCase();
      if (text === "timer" || text === "retornos") return "timer";
      if (text === "all" || text === "todos") return "all";
      return "principal";
    };

    const safeAdminNumber = (value: unknown): number => {
      const parsed = Number(value || 0);
      return Number.isFinite(parsed) ? parsed : 0;
    };

    const clampAdminInteger = (value: unknown, fallback: number, min: number, max: number): number => {
      const parsed = Math.floor(Number(value));
      if (!Number.isFinite(parsed)) return fallback;
      return Math.max(min, Math.min(max, parsed));
    };

    const recentPage = clampAdminInteger(req.query?.page, 1, 1, 200);
    const recentPageSize = clampAdminInteger(req.query?.pageSize, 30, 10, 80);
    const recentSource = normalizeAdminRecentSource(req.query?.source);
    const recentOffset = (recentPage - 1) * recentPageSize;
    const recentFetchLimit = Math.min(recentOffset + recentPageSize + 40, 240);

    const sanitizeAdminQueueJob = (job: any) => {
      const contactSuffix = maskAdminQueuePhone(job.contactNumber);
      return {
        source: job.source,
        id: stableAdminLabel(job.id, "item"),
        status: job.status,
        retryCount: job.retryCount,
        failureReason: sanitizeAdminQueueText(job.failureReason, 180) || null,
        createdAt: job.createdAt,
        executeAt: job.executeAt,
        updatedAt: job.updatedAt,
        ageSeconds: job.ageSeconds,
        elapsedSeconds: job.elapsedSeconds,
        jobTotalSeconds: job.jobTotalSeconds ?? job.elapsedSeconds ?? null,
        scheduledWaitSeconds: job.scheduledWaitSeconds ?? null,
        queueLagSeconds: job.queueLagSeconds ?? null,
        processingSeconds: job.processingSeconds ?? null,
        whatsappToAppSeconds: job.whatsappToAppSeconds ?? null,
        responseTimeSeconds: job.responseTimeSeconds ?? null,
        deliveryStatus: normalizeAdminDeliveryStatus(job.deliveryStatus),
        lastCustomerAt: job.lastCustomerAt || null,
        lastCustomerPersistedAt: job.lastCustomerPersistedAt || null,
        firstAgentAt: job.firstAgentAt || null,
        firstAgentPersistedAt: job.firstAgentPersistedAt || null,
        contactLabel: contactSuffix || (job.contactName ? "cliente com nome" : "cliente"),
        contactSuffix: contactSuffix || null,
        accountLabel: stableAdminLabel(job.email || job.conversationId, "conta"),
        conversationLabel: stableAdminLabel(job.conversationId, "conversa"),
      };
    };

    const sanitizeOutboundQueueStats = (stats: any) => {
      const queues = stats?.queues && typeof stats.queues === "object" ? stats.queues : {};
      const safeQueues: Record<string, any> = {};
      for (const [rawKey, queue] of Object.entries(queues)) {
        const safeKey = stableAdminLabel(rawKey, "canal");
        const item = queue && typeof queue === "object" && !Array.isArray(queue)
          ? queue as Record<string, any>
          : {};
        safeQueues[safeKey] = {
          queueLength: safeAdminNumber(item.queueLength),
          isProcessing: item.isProcessing === true,
          directExecutionPending: safeAdminNumber(item.directExecutionPending),
          totalSent: safeAdminNumber(item.totalSent),
          totalErrors: safeAdminNumber(item.totalErrors),
          lastSentAt: item.lastSentAt || null,
          oldestQueuedAgeMs: safeAdminNumber(item.oldestQueuedAgeMs),
          priorityBreakdown: item.priorityBreakdown && typeof item.priorityBreakdown === "object" && !Array.isArray(item.priorityBreakdown)
            ? item.priorityBreakdown
            : {},
          isPaused: item.isPaused === true,
          pauseRemainingMs: safeAdminNumber(item.pauseRemainingMs),
        };
      }

      return {
        totalQueues: safeAdminNumber(stats?.totalQueues),
        queues: safeQueues,
      };
    };

    const sanitizeRuntimeQueueStatus = (runtime: any) => {
      const mapRun = (run: any) => {
        const contactSuffix = maskAdminQueuePhone(run?.contactSuffix);
        return {
          id: stableAdminLabel(run?.runId || run?.conversationHash || run?.userHash, "atendimento"),
          clientLabel: contactSuffix || stableAdminLabel(run?.conversationHash || run?.runId, "cliente"),
          contactSuffix: contactSuffix || null,
          currentStage: normalizeAdminRuntimeStage(run?.currentStage),
          queuedAt: run?.queuedAt || null,
          startedAt: run?.startedAt || null,
          waitMs: safeAdminNumber(run?.waitMs),
          elapsedMs: safeAdminNumber(run?.elapsedMs),
        };
      };

      return {
        enabled: runtime?.enabled === true,
        generatedAt: runtime?.generatedAt || new Date().toISOString(),
        activeSlots: safeAdminNumber(runtime?.activeSlots),
        maxConcurrent: safeAdminNumber(runtime?.maxConcurrent),
        queueLength: safeAdminNumber(runtime?.queueLength),
        maxQueue: safeAdminNumber(runtime?.maxQueue),
        queueTimeoutMs: safeAdminNumber(runtime?.queueTimeoutMs),
        activeRuns: Array.isArray(runtime?.activeRuns) ? runtime.activeRuns.map(mapRun) : [],
        queuedRuns: Array.isArray(runtime?.queuedRuns) ? runtime.queuedRuns.map(mapRun) : [],
        recentCompleted: safeAdminNumber(runtime?.recentCompleted),
        averageRunMs: runtime?.averageRunMs == null ? null : safeAdminNumber(runtime?.averageRunMs),
        recentEvents: Array.isArray(runtime?.recentEvents)
          ? runtime.recentEvents.map((event: any) => ({
            id: stableAdminLabel(event?.id || event?.runId || event?.at, "evento"),
            kind: normalizeAdminEventKind(event?.kind),
            at: event?.at || null,
            ageMs: safeAdminNumber(event?.ageMs),
            clientLabel: maskAdminQueuePhone(event?.contactSuffix) || stableAdminLabel(event?.conversationHash || event?.runId, "cliente"),
            contactSuffix: maskAdminQueuePhone(event?.contactSuffix) || null,
            stage: normalizeAdminRuntimeStage(event?.stage),
            durationMs: event?.durationMs == null ? null : safeAdminNumber(event?.durationMs),
            waitMs: event?.waitMs == null ? null : safeAdminNumber(event?.waitMs),
            totalMs: event?.totalMs == null ? null : safeAdminNumber(event?.totalMs),
            error: sanitizeAdminQueueText(event?.error, 180) || null,
          }))
          : [],
      };
    };

    const buildRuntimeRecentJobs = (runtime: any) => {
      const nowMs = Date.now();
      const events = Array.isArray(runtime?.recentEvents) ? runtime.recentEvents : [];
      const activeByRun = new Map<string, any>(
        (Array.isArray(runtime?.activeRuns) ? runtime.activeRuns : [])
          .map((run: any) => [String(run?.runId || ""), run])
          .filter(([runId]) => Boolean(runId)),
      );
      const queuedByRun = new Map<string, any>(
        (Array.isArray(runtime?.queuedRuns) ? runtime.queuedRuns : [])
          .map((run: any) => [String(run?.runId || ""), run])
          .filter(([runId]) => Boolean(runId)),
      );
      const grouped = new Map<string, any[]>();
      for (const event of events) {
        const runId = String(event?.runId || "").trim();
        if (!runId) continue;
        const group = grouped.get(runId) || [];
        group.push(event);
        grouped.set(runId, group);
      }
      for (const run of activeByRun.values()) {
        const runId = String(run?.runId || "").trim();
        if (runId && !grouped.has(runId)) grouped.set(runId, []);
      }
      for (const run of queuedByRun.values()) {
        const runId = String(run?.runId || "").trim();
        if (runId && !grouped.has(runId)) grouped.set(runId, []);
      }

      const toSeconds = (value: unknown): number | null => {
        const parsed = Number(value);
        if (!Number.isFinite(parsed) || parsed < 0) return null;
        return Math.max(0, Math.round(parsed / 1000));
      };
      const eventTimeMs = (event: any): number => {
        const atMs = Number(event?.atMs);
        if (Number.isFinite(atMs) && atMs > 0) return atMs;
        const parsed = Date.parse(String(event?.at || ""));
        return Number.isFinite(parsed) ? parsed : 0;
      };

      return Array.from(grouped.entries()).map(([runId, group]) => {
        const sorted = group
          .slice()
          .sort((a, b) => eventTimeMs(b) - eventTimeMs(a));
        const latest = sorted[0] || null;
        const first = sorted.length ? sorted[sorted.length - 1] : null;
        const completed = sorted.find((event) => String(event?.kind || "") === "completed") || null;
        const failed = sorted.find((event) => String(event?.kind || "") === "failed") || null;
        const activeRun = activeByRun.get(runId) || null;
        const queuedRun = queuedByRun.get(runId) || null;
        const status = failed
          ? "failed"
          : completed
            ? "completed"
            : activeRun || ["started", "target_started", "target_failed"].includes(String(latest?.kind || ""))
              ? "processing"
              : "pending";
        const createdAt =
          activeRun?.createdAt ||
          queuedRun?.createdAt ||
          first?.at ||
          latest?.at ||
          new Date(nowMs).toISOString();
        const updatedAt = latest?.at || activeRun?.startedAt || queuedRun?.queuedAt || createdAt;
        const elapsedMs =
          status === "processing" && activeRun
            ? Number(activeRun.elapsedMs || 0)
            : Number(completed?.totalMs ?? failed?.totalMs ?? latest?.totalMs ?? 0);
        const fallbackElapsedMs = (() => {
          const start = Date.parse(String(createdAt || ""));
          const end = Date.parse(String(updatedAt || ""));
          if (Number.isFinite(start) && Number.isFinite(end) && end >= start) return end - start;
          return 0;
        })();
        const jobTotalSeconds = toSeconds(elapsedMs || fallbackElapsedMs);
        const processingSeconds = toSeconds(
          status === "processing" && activeRun
            ? activeRun.elapsedMs
            : completed?.durationMs ?? failed?.durationMs ?? latest?.durationMs ?? elapsedMs,
        );
        const stage = completed?.stage || failed?.stage || latest?.stage || activeRun?.currentStage || queuedRun?.currentStage || "";
        const contactNumber = latest?.contactSuffix || activeRun?.contactSuffix || queuedRun?.contactSuffix || "";
        const conversationId = latest?.conversationHash || activeRun?.conversationHash || queuedRun?.conversationHash || runId;

        return {
          source: "principal",
          id: `runtime:${runId}`,
          conversationId,
          status,
          retryCount: sorted.filter((event) => String(event?.kind || "") === "target_failed").length,
          failureReason: failed?.error || (status === "processing" ? "Atendimento em andamento" : "Atendimento registrado em tempo real"),
          createdAt,
          executeAt: createdAt,
          updatedAt,
          ageSeconds: Math.max(0, Math.round((nowMs - Date.parse(String(createdAt || ""))) / 1000)) || 0,
          elapsedSeconds: jobTotalSeconds,
          jobTotalSeconds,
          scheduledWaitSeconds: toSeconds(activeRun?.waitMs ?? queuedRun?.waitMs) || 0,
          queueLagSeconds: null,
          processingSeconds,
          whatsappToAppSeconds: null,
          responseTimeSeconds: status === "completed" ? jobTotalSeconds : null,
          lastCustomerAt: null,
          lastCustomerPersistedAt: null,
          firstAgentAt: status === "completed" ? updatedAt : null,
          firstAgentPersistedAt: status === "completed" ? updatedAt : null,
          deliveryStatus: null,
          contactNumber,
          contactName: stage ? `cliente ${stage}` : null,
          email: conversationId,
        };
      });
    };

    const safeQuery = async (label: string, query: string, params: any[] = []) => {
      try {
        return await pool.query(query, params);
      } catch (error: any) {
        console.warn(`[Admin Queue] ${label} unavailable:`, error?.message || error);
        return { rows: [], rowCount: 0, error: error?.message || String(error) };
      }
    };

    try {
      const [
        jobSummary,
        legacySummary,
        activeJobs,
        legacyJobs,
        pendingIncoming,
        directLatency,
        connectionEvents,
      ] = await Promise.all([
        safeQuery("job_summary", `
          SELECT
            status,
            COUNT(*)::int AS total,
            MIN(created_at) AS "oldestAt",
            MAX(updated_at) AS "newestAt",
            MAX(COALESCE(retry_count, 0))::int AS "maxRetry"
          FROM vercel_agent_response_jobs
          WHERE created_at >= NOW() - INTERVAL '2 hours'
             OR status IN ('pending', 'processing')
          GROUP BY status
          ORDER BY status
        `),
        safeQuery("legacy_summary", `
          SELECT
            status,
            COUNT(*)::int AS total,
            MIN(created_at) AS "oldestAt",
            MAX(updated_at) AS "newestAt",
            MAX(COALESCE(retry_count, 0))::int AS "maxRetry"
          FROM pending_ai_responses
          WHERE created_at >= NOW() - INTERVAL '2 hours'
             OR status IN ('pending', 'processing')
          GROUP BY status
          ORDER BY status
        `),
        safeQuery("active_jobs", `
          WITH candidate_jobs AS (
            SELECT j.*
            FROM vercel_agent_response_jobs j
            WHERE j.created_at >= NOW() - INTERVAL '2 hours'
               OR j.updated_at >= NOW() - INTERVAL '2 hours'
               OR j.status IN ('pending', 'processing')
            ORDER BY
              CASE WHEN j.status = 'processing' THEN 0 WHEN j.status = 'pending' THEN 1 ELSE 2 END,
              COALESCE(j.updated_at, j.execute_at, j.created_at) DESC
            LIMIT $1
          )
          SELECT
            'principal' AS source,
            j.id::text AS id,
            j.conversation_id AS "conversationId",
            j.status,
            COALESCE(j.retry_count, 0)::int AS "retryCount",
            LEFT(COALESCE(j.failure_reason, ''), 220) AS "failureReason",
            j.created_at AS "createdAt",
            j.execute_at AS "executeAt",
            j.updated_at AS "updatedAt",
            EXTRACT(EPOCH FROM (NOW() - j.created_at))::int AS "ageSeconds",
            EXTRACT(EPOCH FROM (COALESCE(j.updated_at, NOW()) - j.created_at))::int AS "elapsedSeconds",
            EXTRACT(EPOCH FROM (COALESCE(j.updated_at, NOW()) - j.created_at))::int AS "jobTotalSeconds",
            GREATEST(0, EXTRACT(EPOCH FROM (COALESCE(j.execute_at, j.created_at) - j.created_at)))::int AS "scheduledWaitSeconds",
            CASE
              WHEN j.last_attempt_at IS NULL OR j.execute_at IS NULL THEN NULL
              ELSE GREATEST(0, EXTRACT(EPOCH FROM (j.last_attempt_at - j.execute_at)))::int
            END AS "queueLagSeconds",
            CASE
              WHEN j.last_attempt_at IS NULL THEN NULL
              ELSE GREATEST(0, EXTRACT(EPOCH FROM (COALESCE(j.updated_at, NOW()) - j.last_attempt_at)))::int
            END AS "processingSeconds",
            CASE
              WHEN customer_msg.msg_at IS NULL OR customer_msg.persisted_at IS NULL THEN NULL
              ELSE GREATEST(0, EXTRACT(EPOCH FROM (customer_msg.persisted_at - customer_msg.msg_at)))::int
            END AS "whatsappToAppSeconds",
            CASE
              WHEN customer_msg.msg_at IS NULL OR agent_msg.msg_at IS NULL THEN NULL
              ELSE GREATEST(0, EXTRACT(EPOCH FROM (agent_msg.msg_at - customer_msg.msg_at)))::int
            END AS "responseTimeSeconds",
            customer_msg.msg_at AS "lastCustomerAt",
            customer_msg.persisted_at AS "lastCustomerPersistedAt",
            agent_msg.msg_at AS "firstAgentAt",
            agent_msg.persisted_at AS "firstAgentPersistedAt",
            agent_msg.status AS "deliveryStatus",
            c.contact_number AS "contactNumber",
            c.contact_name AS "contactName",
            u.email
          FROM candidate_jobs j
          LEFT JOIN conversations c ON c.id = j.conversation_id
          LEFT JOIN whatsapp_connections wc ON wc.id = c.connection_id
          LEFT JOIN users u ON u.id::text = wc.user_id::text
          LEFT JOIN LATERAL (
            SELECT
              COALESCE(m.timestamp, m.created_at) AS msg_at,
              m.created_at AS persisted_at,
              m.status AS status
            FROM messages m
            WHERE m.conversation_id = j.conversation_id
              AND m.from_me = false
              AND COALESCE(m.timestamp, m.created_at) <= COALESCE(j.updated_at, NOW()) + INTERVAL '5 seconds'
              AND (
                j.message_id IS NULL
                OR m.message_id = j.message_id
                OR COALESCE(m.timestamp, m.created_at) >= j.created_at - INTERVAL '30 minutes'
              )
            ORDER BY
              CASE WHEN j.message_id IS NOT NULL AND m.message_id = j.message_id THEN 0 ELSE 1 END,
              COALESCE(m.timestamp, m.created_at) DESC,
              m.created_at DESC
            LIMIT 1
          ) customer_msg ON true
          LEFT JOIN LATERAL (
            SELECT
              COALESCE(m.timestamp, m.created_at) AS msg_at,
              m.created_at AS persisted_at,
              m.status AS status
            FROM messages m
            WHERE m.conversation_id = j.conversation_id
              AND m.from_me = true
              AND COALESCE(m.is_from_agent, false) = true
              AND customer_msg.msg_at IS NOT NULL
              AND COALESCE(m.timestamp, m.created_at) >= customer_msg.msg_at
              AND COALESCE(m.timestamp, m.created_at) <= COALESCE(j.updated_at, NOW()) + INTERVAL '5 minutes'
            ORDER BY COALESCE(m.timestamp, m.created_at) ASC, m.created_at ASC
            LIMIT 1
          ) agent_msg ON true
        `, [recentFetchLimit]),
        safeQuery("legacy_jobs", `
          WITH candidate_jobs AS (
            SELECT p.*
            FROM pending_ai_responses p
            WHERE p.created_at >= NOW() - INTERVAL '2 hours'
               OR p.updated_at >= NOW() - INTERVAL '2 hours'
               OR p.status IN ('pending', 'processing')
            ORDER BY
              CASE WHEN p.status = 'processing' THEN 0 WHEN p.status = 'pending' THEN 1 ELSE 2 END,
              COALESCE(p.updated_at, p.execute_at, p.created_at) DESC
            LIMIT $1
          )
          SELECT
            'timer' AS source,
            p.id::text AS id,
            p.conversation_id AS "conversationId",
            p.status,
            COALESCE(p.retry_count, 0)::int AS "retryCount",
            LEFT(COALESCE(p.failure_reason, p.last_error, ''), 220) AS "failureReason",
            p.created_at AS "createdAt",
            p.execute_at AS "executeAt",
            p.updated_at AS "updatedAt",
            EXTRACT(EPOCH FROM (NOW() - p.created_at))::int AS "ageSeconds",
            EXTRACT(EPOCH FROM (COALESCE(p.updated_at, NOW()) - p.created_at))::int AS "elapsedSeconds",
            EXTRACT(EPOCH FROM (COALESCE(p.updated_at, NOW()) - p.created_at))::int AS "jobTotalSeconds",
            GREATEST(0, EXTRACT(EPOCH FROM (COALESCE(p.execute_at, p.created_at) - p.created_at)))::int AS "scheduledWaitSeconds",
            CASE
              WHEN p.last_attempt_at IS NULL OR p.execute_at IS NULL THEN NULL
              ELSE GREATEST(0, EXTRACT(EPOCH FROM (p.last_attempt_at - p.execute_at)))::int
            END AS "queueLagSeconds",
            CASE
              WHEN p.last_attempt_at IS NULL THEN NULL
              ELSE GREATEST(0, EXTRACT(EPOCH FROM (COALESCE(p.updated_at, NOW()) - p.last_attempt_at)))::int
            END AS "processingSeconds",
            CASE
              WHEN customer_msg.msg_at IS NULL OR customer_msg.persisted_at IS NULL THEN NULL
              ELSE GREATEST(0, EXTRACT(EPOCH FROM (customer_msg.persisted_at - customer_msg.msg_at)))::int
            END AS "whatsappToAppSeconds",
            NULL::int AS "responseTimeSeconds",
            customer_msg.msg_at AS "lastCustomerAt",
            customer_msg.persisted_at AS "lastCustomerPersistedAt",
            agent_msg.msg_at AS "firstAgentAt",
            agent_msg.persisted_at AS "firstAgentPersistedAt",
            agent_msg.status AS "deliveryStatus",
            COALESCE(c.contact_number, p.contact_number) AS "contactNumber",
            c.contact_name AS "contactName",
            u.email
          FROM candidate_jobs p
          LEFT JOIN conversations c ON c.id = p.conversation_id
          LEFT JOIN whatsapp_connections wc ON wc.id = c.connection_id
          LEFT JOIN users u ON u.id::text = COALESCE(wc.user_id::text, p.user_id::text)
          LEFT JOIN LATERAL (
            SELECT
              COALESCE(m.timestamp, m.created_at) AS msg_at,
              m.created_at AS persisted_at,
              m.status AS status
            FROM messages m
            WHERE m.conversation_id = p.conversation_id
              AND m.from_me = false
              AND COALESCE(m.timestamp, m.created_at) <= COALESCE(p.updated_at, NOW()) + INTERVAL '5 seconds'
              AND COALESCE(m.timestamp, m.created_at) >= COALESCE(p.last_attempt_at, p.execute_at, p.updated_at, p.created_at) - INTERVAL '2 minutes'
            ORDER BY COALESCE(m.timestamp, m.created_at) DESC, m.created_at DESC
            LIMIT 1
          ) customer_msg ON true
          LEFT JOIN LATERAL (
            SELECT
              COALESCE(m.timestamp, m.created_at) AS msg_at,
              m.created_at AS persisted_at,
              m.status AS status
            FROM messages m
            WHERE m.conversation_id = p.conversation_id
              AND m.from_me = true
              AND COALESCE(m.is_from_agent, false) = true
              AND COALESCE(m.timestamp, m.created_at) >= COALESCE(customer_msg.msg_at, p.last_attempt_at, p.execute_at, p.created_at)
              AND COALESCE(m.timestamp, m.created_at) <= COALESCE(p.updated_at, NOW()) + INTERVAL '5 minutes'
            ORDER BY COALESCE(m.timestamp, m.created_at) ASC, m.created_at ASC
            LIMIT 1
          ) agent_msg ON true
        `, [recentFetchLimit]),
        safeQuery("pending_incoming", `
          SELECT
            status,
            COUNT(*)::int AS total,
            MIN(received_at) AS "oldestReceivedAt",
            MAX(received_at) AS "newestReceivedAt",
            MAX(COALESCE(process_attempts, 0))::int AS "maxAttempts"
          FROM pending_incoming_messages
          WHERE status IN ('pending', 'processing', 'failed')
             OR received_at >= NOW() - INTERVAL '2 hours'
          GROUP BY status
          ORDER BY status
        `),
        safeQuery("direct_latency", `
          WITH recent_direct AS (
            SELECT
              EXTRACT(EPOCH FROM (m.created_at - m.timestamp))::int AS persist_delay_seconds,
              CASE
                WHEN incoming_log.received_at IS NULL THEN NULL
                ELSE GREATEST(0, EXTRACT(EPOCH FROM (m.created_at - incoming_log.received_at)))::int
              END AS app_persist_seconds
            FROM (
              SELECT conversation_id, created_at, timestamp, message_id
              FROM messages
              WHERE timestamp >= NOW() - INTERVAL '2 hours'
                AND timestamp IS NOT NULL
                AND from_me = false
              ORDER BY timestamp DESC
              LIMIT 800
            ) m
            JOIN conversations c ON c.id = m.conversation_id
            LEFT JOIN LATERAL (
              SELECT received_at
              FROM incoming_message_log l
              WHERE l.whatsapp_message_id = m.message_id
              ORDER BY received_at ASC
              LIMIT 1
            ) incoming_log ON true
            WHERE m.created_at >= NOW() - INTERVAL '2 hours'
              AND NOT (
                COALESCE(c.jid_suffix, '') = 'g.us'
                OR COALESCE(c.remote_jid, '') LIKE '%@g.us'
                OR COALESCE(c.remote_jid, '') LIKE '%@newsletter%'
                OR COALESCE(c.remote_jid, '') = 'status@broadcast'
              )
            ORDER BY m.created_at DESC
            LIMIT 500
          )
          SELECT
            COUNT(*)::int AS "directInbound",
            percentile_cont(0.5) WITHIN GROUP (ORDER BY persist_delay_seconds) AS "p50PersistSeconds",
            percentile_cont(0.9) WITHIN GROUP (ORDER BY persist_delay_seconds) AS "p90PersistSeconds",
            percentile_cont(0.95) WITHIN GROUP (ORDER BY persist_delay_seconds) AS "p95PersistSeconds",
            MAX(persist_delay_seconds)::int AS "maxPersistSeconds",
            COUNT(*) FILTER (WHERE persist_delay_seconds > 120)::int AS "over120Seconds",
            COUNT(app_persist_seconds)::int AS "matchedIncomingLogs",
            percentile_cont(0.9) WITHIN GROUP (ORDER BY app_persist_seconds) AS "p90AppPersistSeconds",
            MAX(app_persist_seconds)::int AS "maxAppPersistSeconds",
            COUNT(*) FILTER (WHERE app_persist_seconds > 5)::int AS "appOver5Seconds"
          FROM recent_direct
        `),
        safeQuery("connection_events", `
          WITH watched(event_type) AS (
            VALUES ('connected'), ('disconnected'), ('messages_recovered')
          ),
          recent AS (
            SELECT item.event_type, item.created_at
            FROM watched
            CROSS JOIN LATERAL (
              SELECT event_type, created_at
              FROM connection_health_log
              WHERE event_type = watched.event_type
                AND created_at >= NOW() - INTERVAL '2 hours'
              ORDER BY created_at DESC
              LIMIT 200
            ) item
          )
          SELECT
            event_type AS "eventType",
            COUNT(*)::int AS total,
            MAX(created_at) AS "lastAt"
          FROM recent
          GROUP BY event_type
          ORDER BY total DESC
          LIMIT 10
        `),
      ]);

      const rawRuntime = null;
      const runtime = sanitizeRuntimeQueueStatus(rawRuntime);
      const runtimeRecentJobs: any[] = [];
      const outbound = sanitizeOutboundQueueStats(messageQueueService.getStats());
      const allRecentJobs = [
        ...runtimeRecentJobs,
        ...(recentSource !== "timer" ? activeJobs.rows : []),
        ...(recentSource !== "principal" ? legacyJobs.rows : []),
      ]
        .sort((a: any, b: any) => {
          const aActive = a.status === "processing" ? 0 : a.status === "pending" ? 1 : 2;
          const bActive = b.status === "processing" ? 0 : b.status === "pending" ? 1 : 2;
          if (aActive !== bActive) return aActive - bActive;
          return new Date(b.updatedAt || b.createdAt || 0).getTime() - new Date(a.updatedAt || a.createdAt || 0).getTime();
        });
      const recentJobs = allRecentJobs
        .slice(recentOffset, recentOffset + recentPageSize)
        .map(sanitizeAdminQueueJob);

      const safeIncoming = pendingIncoming.rows.map((row: any) => ({
        status: String(row.status || ""),
        total: safeAdminNumber(row.total),
        oldestReceivedAt: row.oldestReceivedAt || null,
        newestReceivedAt: row.newestReceivedAt || null,
        maxAttempts: safeAdminNumber(row.maxAttempts),
      }));
      const safeConnectionEvents = connectionEvents.rows.map((row: any) => ({
        eventType: normalizeAdminConnectionEventType(row.eventType),
        total: safeAdminNumber(row.total),
        lastAt: row.lastAt || null,
      }));

      res.json({
        generatedAt: new Date().toISOString(),
        runtime,
        outbound,
        persistent: {
          jobSummary: jobSummary.rows,
          legacySummary: legacySummary.rows,
          recentJobs,
          recentJobsPage: {
            page: recentPage,
            pageSize: recentPageSize,
            source: recentSource,
            hasMore: allRecentJobs.length > recentOffset + recentPageSize,
            totalLoaded: allRecentJobs.length,
          },
        },
        incoming: safeIncoming,
        directLatency2h: directLatency.rows[0] || null,
        connectionEvents: safeConnectionEvents,
      });
    } catch (error: any) {
      console.error("[Admin Queue] Error fetching AI queue status:", error);
      res.status(500).json({ message: "Failed to fetch AI queue status" });
    }
  });



