  app.get("/api/admin/conversation-monitor", isAdmin, async (req: any, res) => {
    try {
      const rawLimit = Number(req.query?.limit || 50);
      const rawOffset = Number(req.query?.offset || 0);
      const limit = Math.max(1, Math.min(50, Number.isFinite(rawLimit) ? Math.floor(rawLimit) : 50));
      const offset = Math.max(0, Math.min(5000, Number.isFinite(rawOffset) ? Math.floor(rawOffset) : 0));
      const search = String(req.query?.search || "").trim();
      const rawScope = String(req.query?.scope || "direct").trim().toLowerCase();
      const scope = rawScope === "groups" ? "groups" : "direct";
      const aiFilter = String(req.query?.ai || "all").trim().toLowerCase();
      const params: unknown[] = [];
      const groupConversationSql = `(COALESCE(c.jid_suffix, 's.whatsapp.net') = 'g.us' OR COALESCE(c.remote_jid, '') ILIKE '%@g.us')`;
      const scopeClause = scope === "groups" ? `AND ${groupConversationSql}` : `AND NOT ${groupConversationSql}`;
      const aiActiveSql = `(COALESCE(wc.ai_enabled, false) = true AND COALESCE(aic.is_active, false) = true AND adc.conversation_id IS NULL AND NOT ${groupConversationSql})`;
      const aiClause = aiFilter === "active" ? `AND ${aiActiveSql}` : "";
      let searchClause = "";

      if (search) {
        params.push(`%${search}%`);
        searchClause = `
          AND (
            c.contact_name ILIKE $${params.length}
            OR c.contact_number ILIKE $${params.length}
            OR c.last_message_text ILIKE $${params.length}
            OR u.email ILIKE $${params.length}
            OR u.name ILIKE $${params.length}
            OR wc.phone_number ILIKE $${params.length}
          )
        `;
      }

      params.push(limit + 1);
      const limitParam = params.length;
      params.push(offset);
      const offsetParam = params.length;

      const result = await pool.query(
        `
          SELECT
            c.id,
            c.connection_id AS "connectionId",
            c.contact_number AS "contactNumber",
            c.remote_jid AS "remoteJid",
            c.jid_suffix AS "jidSuffix",
            ${groupConversationSql} AS "isGroup",
            c.contact_name AS "contactName",
            c.contact_avatar AS "contactAvatar",
            c.last_message_text AS "lastMessageText",
            c.last_message_time AS "lastMessageTime",
            c.last_message_from_me AS "lastMessageFromMe",
            c.unread_count AS "unreadCount",
            c.is_archived AS "isArchived",
            c.followup_active AS "followupActive",
            c.needs_human_attention AS "needsHumanAttention",
            c.attention_priority AS "attentionPriority",
            wc.user_id AS "userId",
            wc.connection_name AS "connectionName",
            wc.phone_number AS "connectionPhone",
            wc.is_connected AS "connectionConnected",
            wc.ai_enabled AS "connectionAiEnabled",
            wc.provider_status AS "providerStatus",
            u.email AS "ownerEmail",
            u.name AS "ownerName",
            COALESCE(aic.is_active, false) AS "agentActive",
            (adc.conversation_id IS NOT NULL) AS "agentDisabledForConversation",
            ${aiActiveSql} AS "conversationAiActive",
            COALESCE(bac.agent_name, CASE WHEN COALESCE(aic.is_active, false) THEN 'Agente IA' ELSE NULL END) AS "agentName"
          FROM conversations c
          INNER JOIN whatsapp_connections wc ON wc.id = c.connection_id
          LEFT JOIN users u ON u.id = wc.user_id
          LEFT JOIN ai_agent_config aic ON aic.user_id = wc.user_id
          LEFT JOIN business_agent_configs bac ON bac.user_id = wc.user_id AND bac.is_active = true
          LEFT JOIN agent_disabled_conversations adc ON adc.conversation_id = c.id
          WHERE COALESCE(c.is_closed, false) = false
            AND COALESCE(c.is_archived, false) = false
            ${scopeClause}
            ${aiClause}
            ${searchClause}
          ORDER BY COALESCE(c.last_message_time, c.updated_at, c.created_at) DESC NULLS LAST, c.id DESC
          LIMIT $${limitParam}
          OFFSET $${offsetParam}
        `,
        params,
      );

      const rows = result.rows || [];
      res.json({
        items: rows.slice(0, limit),
        pagination: {
          limit,
          offset,
          hasMore: rows.length > limit,
          nextOffset: offset + Math.min(limit, rows.length),
        },
        readOnly: true,
      });
    } catch (error) {
      console.error("Error fetching admin conversation monitor:", error);
      res.status(500).json({ message: "Failed to fetch conversation monitor" });
    }
  });

