  // Envio em massa para grupos

  app.post("/api/whatsapp/groups/bulk-send", isAuthenticated, async (req: any, res) => {

    try {

      const userId = getUserId(req);
      if (!(await requirePlusPlanForLegacyToolAction(req, res))) {
        return;
      }

      const { groupIds, groupTargets, message, settings, scheduledAt, connectionId, mediaUrl, mediaType, metadata } = req.body;
      const normalizedMediaUrl = String(mediaUrl || "").trim();
      const rawMediaType = String(mediaType || "image").trim().toLowerCase();
      const normalizedMediaType = normalizedMediaUrl
        ? ["video", "audio", "document"].includes(rawMediaType)
          ? rawMediaType
          : "image"
        : null;



      if (!groupIds || !Array.isArray(groupIds) || groupIds.length === 0) {

        return res.status(400).json({ message: "Lista de grupos e obrigatoria" });

      }



      if ((!message || typeof message !== "string" || !message.trim()) && !normalizedMediaUrl) {

        return res.status(400).json({ message: "Mensagem ou midia e obrigatoria" });

      }



      const normalizedGroupIds = groupIds.map((groupId: unknown) => String(groupId || "").trim()).filter(Boolean);
      const normalizedGroupTargets = Array.isArray(groupTargets)
        ? groupTargets
            .map((target: any) => ({
              groupId: String(target?.groupId || "").trim(),
              connectionId: String(target?.connectionId || "").trim(),
            }))
            .filter((target: any) => target.groupId)
        : [];
      const targetConnectionIds = Array.from(
        new Set(
          [
            ...normalizedGroupTargets.map((target: any) => target.connectionId).filter(Boolean),
            String(connectionId || "").trim(),
          ].filter(Boolean),
        ),
      );

      const groupsRuntimeConnections = await resolveGroupsRuntimeConnections(userId, targetConnectionIds);

      if (groupsRuntimeConnections.length === 0) {
        return res.status(400).json({
          message: "Nenhuma conexao WhatsApp conectada foi encontrada para enviar em grupos",
        });
      }

      const runtimeByConnectionId = new Map(
        groupsRuntimeConnections.map((runtimeConnection) => [runtimeConnection.connection.id, runtimeConnection]),
      );
      const missingConnectionIds = targetConnectionIds.filter((targetId) => !runtimeByConnectionId.has(targetId));
      if (missingConnectionIds.length > 0) {
        return res.status(400).json({
          message: "Uma ou mais conexoes selecionadas nao estao conectadas para envio em grupos",
          connectionIds: missingConnectionIds,
        });
      }

      const fallbackRuntimeConnection = groupsRuntimeConnections[0];
      const targetByGroupId = new Map(
        normalizedGroupTargets.map((target: any) => [target.groupId, target.connectionId || ""]),
      );
      const groupIdsByConnection = new Map<string, string[]>();

      for (const groupId of normalizedGroupIds) {
        const targetConnectionId = targetByGroupId.get(groupId);
        const runtimeConnection =
          (targetConnectionId ? runtimeByConnectionId.get(targetConnectionId) : null) ||
          fallbackRuntimeConnection;

        if (!runtimeConnection) {
          continue;
        }

        const list = groupIdsByConnection.get(runtimeConnection.connection.id) || [];
        list.push(groupId);
        groupIdsByConnection.set(runtimeConnection.connection.id, list);
      }

      if (groupIdsByConnection.size === 0) {
        return res.status(400).json({ message: "Nenhum grupo valido encontrado para envio" });
      }



      // Configuracoes de delay

      const delayMin = settings?.delayMin || 5;

      const delayMax = settings?.delayMax || 15;

      const useAI = settings?.useAI || false;



      // Buscar metadados dos grupos para nomes

      let groupsMetadata: Record<string, string> = {};

      try {

        for (const [runtimeConnectionId, selectedGroupIds] of Array.from(groupIdsByConnection.entries())) {
          const runtimeConnection = runtimeByConnectionId.get(runtimeConnectionId);
          if (!runtimeConnection) {
            continue;
          }

          const { connection, owner } = runtimeConnection;
          const groups: GroupsListResult =
            owner === "gateway"
              ? await listGatewayInstanceGroups(connection.id) as GroupsListResult
              : await fetchUserGroups(userId, connection.id);

          const selectedGroupIdSet = new Set(selectedGroupIds);
          groupsMetadata = {
            ...groupsMetadata,
            ...groups
              .filter((group: any) => selectedGroupIdSet.has(group.id))
              .reduce((acc: Record<string, string>, group: any) => ({
                ...acc,
                [group.id]: group.name,
              }), {}),
          };
        }

      } catch (e) {

        console.warn('[GROUP BULK] Nao foi possivel buscar nomes dos grupos');

      }



      // Criar campanha persistida na fila real para acompanhamento e envio com midia.

      const campaignName = `Grupos ${new Date().toLocaleDateString('pt-BR')} ${new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`;

      const campaignId = `group_campaign_${Date.now()}`;

      const scheduledAtDate = scheduledAt ? new Date(scheduledAt) : null;
      const scheduledForFuture =
        scheduledAtDate && Number.isFinite(scheduledAtDate.getTime()) && scheduledAtDate.getTime() > Date.now() + 5000;
      const rawMetadata =
        metadata && typeof metadata === "object" && !Array.isArray(metadata)
          ? metadata as Record<string, unknown>
          : {};
      const campaignContacts = Array.from(groupIdsByConnection.entries()).flatMap(([runtimeConnectionId, selectedGroupIds]) =>
        selectedGroupIds.map((groupId, index) => {
          const normalizedGroupId = String(groupId || "").includes("@g.us") ? String(groupId) : `${groupId}@g.us`;
          return {
            id: `${runtimeConnectionId}:${normalizedGroupId}`,
            phone: normalizedGroupId,
            groupId: normalizedGroupId,
            name: groupsMetadata[groupId] || groupsMetadata[normalizedGroupId] || normalizedGroupId,
            sequenceIndex: index,
            connectionId: runtimeConnectionId,
            kind: "group",
          };
        }),
      );
      const queueMetadata = {
        ...rawMetadata,
        groupTargets: campaignContacts.map((contact) => ({
          groupId: contact.groupId,
          connectionId: contact.connectionId,
          name: contact.name,
        })),
        nextDueAt: scheduledForFuture ? scheduledAtDate!.toISOString() : null,
      };

      await pool.query(
        `
          INSERT INTO broadcast_campaigns (
            id, user_id, connection_id, name, status, message_template, media_url,
            media_type, total_contacts, sent_count, failed_count, campaign_type,
            use_ai, delay_min_ms, delay_max_ms, batch_size, batch_pause_ms,
            contacts_json, results_json, metadata_json, scheduled_at, started_at, completed_at
          )
          VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9,0,0,'group_broadcast',$10,$11,$12,$13,$14,$15::jsonb,'[]'::jsonb,$16::jsonb,$17,$18,NULL)
        `,
        [
          campaignId,
          userId,
          campaignContacts[0]?.connectionId || fallbackRuntimeConnection.connection.id,
          campaignName,
          scheduledForFuture ? "scheduled" : "pending",
          String(message || "").trim(),
          normalizedMediaUrl || null,
          normalizedMediaType,
          campaignContacts.length,
          useAI === true,
          delayMin * 1000,
          delayMax * 1000,
          10,
          20 * 60 * 1000,
          JSON.stringify(campaignContacts),
          JSON.stringify(queueMetadata),
          scheduledForFuture ? scheduledAtDate : null,
          scheduledForFuture ? null : new Date(),
        ],
      );

      if (!scheduledForFuture) {
        broadcastService.startBroadcastCampaignRun(campaignId, "manual");
      }

      res.json({

        success: true,

        total: campaignContacts.length,

        sent: 0,

        failed: 0,

        campaignId,
        id: campaignId,
        scheduled: Boolean(scheduledForFuture),

        progress: {

          total: campaignContacts.length,

          sent: 0,

          failed: 0,

          status: scheduledForFuture ? 'scheduled' : 'running'

        },

        message: scheduledForFuture
          ? `Envio agendado para ${scheduledAtDate!.toLocaleString('pt-BR')}`
          : 'Envio para grupos iniciado.'

      });

      return;

    } catch (error: any) {

      console.error("Error in group bulk send:", error);

      res.status(500).json({ message: error.message || "Falha no envio para grupos" });

    }

  });



