  app.post("/api/test-agent/message", async (req: any, res) => {

    try {

      const { handleTestAgentMessage } = await import("./testAgentService");

      const { getTestToken, processAdminMessage } = await import("./adminAgentService");



      const { message, token, history, userId, sentMedias, sessionId, contactPhone, contactNumber, phone, contactName } = req.body;



      const result = await handleTestAgentMessage(

        { message, token, history, userId, sentMedias, sessionId, contactPhone, contactNumber, phone, contactName }, // ?? Passando sentMedias

        {

          getTestToken,

          getAgentConfig: (id) => storage.getAgentConfig(id),

          processAdminMessage,

          getAgentMediaLibrary,

          generateMediaPromptBlock,

        }

      );

      if ((result as any).emptyResponse) {
        return res.status(502).json({
          success: false,
          emptyResponse: true,
          error: (result as any).error || "empty_real_response",
          response: "",
          splitResponses: [],
          mediaActions: result.mediaActions || [],
        });
      }

      // V23g: Dividir resposta SOMENTE por [BOLHA] - a IA decide quando dividir
      const responseText = result.response || "";
      const explicitBubbleResponses = parseExplicitBubbleMessages(responseText);
      let splitResponses: string[];

      if (explicitBubbleResponses.hasExplicitBubbles) {
        splitResponses = explicitBubbleResponses.parts;
      } else {
        splitResponses = explicitBubbleResponses.parts;
      }

      res.json({
        response: joinBubbleMessages(splitResponses),
        splitResponses,
        mediaActions: result.mediaActions,
      });

    } catch (error: any) {

      console.error("[TEST-AGENT] Erro:", error);

      res.status(500).json({

        error: error.message,

        response: "",
        splitResponses: [],
        mediaActions: [],
        emptyResponse: true,

      });

    }

  });



